### C Implementation

```c
#include <stdio.h>
#include <string.h>

/**
 * @brief Reverses a null-terminated string in place.
 *
 * This function modifies the input string directly by swapping characters
 * from the beginning and the end until the middle of the string is reached.
 *
 * @param str A pointer to the null-terminated string to be reversed.
 */
void reverseStringInPlace(char *str) {
    if (str == NULL) {
        // Handle the case where the input pointer is NULL
        return;
    }

    // 1. Initialize pointers
    int start = 0;
    int end = strlen(str) - 1;
    char temp;

    // 2. Loop until the start pointer crosses or meets the end pointer
    while (start < end) {
        // Swap the characters at the start and end positions
        temp = str[start];
        str[start] = str[end];
        str[end] = temp;

        // Move the pointers inward
        start++;
        end--;
    }
}

// --- Example Usage ---
int main() {
    // Test Case 1: Standard string
    char s1[] = "hello world";
    printf("Original string 1: \"%s\"\n", s1);
    reverseStringInPlace(s1);
    printf("Reversed string 1: \"%s\"\n\n", s1); // Expected: dlrow olleh

    // Test Case 2: Palindrome
    char s2[] = "madam";
    printf("Original string 2: \"%s\"\n", s2);
    reverseStringInPlace(s2);
    printf("Reversed string 2: \"%s\"\n\n", s2); // Expected: madam

    // Test Case 3: Single character
    char s3[] = "a";
    printf("Original string 3: \"%s\"\n", s3);
    reverseStringInPlace(s3);
    printf("Reversed string 3: \"%s\"\n\n", s3); // Expected: a

    // Test Case 4: Empty string
    char s4[] = "";
    printf("Original string 4: \"%s\"\n", s4);
    reverseStringInPlace(s4);
    printf("Reversed string 4: \"%s\"\n\n", s4); // Expected: (empty)

    // Test Case 5: String with spaces
    char s5[] = "race car";
    printf("Original string 5: \"%s\"\n", s5);
    reverseStringInPlace(s5);
    printf("Reversed string 5: \"%s\"\n\n", s5); // Expected: rac ecar

    return 0;
}
```

